contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: target to receive minted tokens, amount to mint
    function run(address target, uint256 mintedAmount) public payable {
        // read before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(target);

        // try minting and record whether it reverted
        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(target);

        // If the call reverted, nothing observable should have changed.
        // If it did not revert, totalSupply and target balance must have increased by exactly mintedAmount.
        assert(
            (reverted && afterTotal == beforeTotal && afterBalance == beforeBalance)
            || (!reverted && afterTotal == beforeTotal + mintedAmount && afterBalance == beforeBalance + mintedAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: caller (ignored since calls originate from this contract), and amount to burn
    function run(address target, uint256 burnAmount) public payable {
        require(target != address(0)); // ensure a valid address param (not strictly about c)

        // read observable initial state
        address ownerBefore = c.owner();
        uint256 totalBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(ownerBefore);

        // Try to call burn as this contract (not owner) and record whether it reverted
        bool revertNonOwner;
        try c.burn(burnAmount) returns (bool ok) {
            revertNonOwner = false;
        } catch {
            revertNonOwner = true;
        }

        // Now, if this test contract happens to be the owner (possible only if constructor of C set owner to this contract),
        // perform burn again but guarded: we must call it as owner exactly once to observe successful effect.
        // Because the checker deploys a fresh C and passes it to this test, it's possible this contract is the owner.
        bool ownerIsThis = (ownerBefore == address(this));
        bool ownerBurnReverted = true;
        uint256 totalAfter = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(ownerBefore);

        if (ownerIsThis) {
            // ensure we have enough balance to attempt burn; if not, reduce amount to available balance
            uint256 attempt = burnAmount;
            if (ownerBalBefore < attempt) {
                attempt = ownerBalBefore;
            }
            try c.burn(attempt) returns (bool ok) {
                ownerBurnReverted = false;
            } catch {
                ownerBurnReverted = true;
            }
            totalAfter = c.totalSupply();
            ownerBalAfter = c.balanceOf(ownerBefore);

            // If owner burn did not revert, it must have decreased both totalSupply and owner's balance by exactly attempt
            assert(ownerBurnReverted || (totalBefore - totalAfter == attempt && ownerBalBefore - ownerBalAfter == attempt));
        }

        // General rule: if caller is not owner, burn must revert; if we are owner and we called burn above, handled by assertion inside branch.
        // express as a single final assert combining observed revertNonOwner and ownerIsThis
        // If we are not the owner, revertNonOwner must be true. If we are the owner, revertNonOwner may be false (first attempt succeeded) or true (first attempt could fail due to insufficient balance),
        // but we already checked the successful owner burn semantics in the branch above. So require: if not owner then revertNonOwner == true.
        assert(ownerIsThis || revertNonOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: fromBalanceHolder is an address whose balance we'll try to transfer from (must be != address(0)),
    // to is the recipient, and amount is the transfer amount to attempt.
    function run(address fromBalanceHolder, address to, uint256 amount) public payable {
        require(fromBalanceHolder != address(0) && to != address(0));

        // Observe totalSupply and balances before the transfer attempt.
        uint256 totalBefore = c.totalSupply();
        uint256 balFromBefore = c.balanceOf(fromBalanceHolder);
        uint256 balToBefore = c.balanceOf(to);

        // Attempt transfer: since calls originate from this contract, we need to simulate that 'fromBalanceHolder' is msg.sender.
        // The contract C's transfer uses msg.sender, so to exercise transfer from 'fromBalanceHolder' we must rely on the fact
        // that initially owner may be this contract or not. We therefore instead call c._transfer via public transfer only from this contract.
        // To test transfer semantics in general we will call c.transfer(to, amount) from THIS contract and observe effects.
        // Record whether the call reverted.
        bool reverted;
        try c.transfer(to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe totals after the attempted transfer.
        uint256 totalAfter = c.totalSupply();
        uint256 balFromAfter = c.balanceOf(fromBalanceHolder);
        uint256 balToAfter = c.balanceOf(to);

        // General rule asserted below:
        // 1) If the transfer succeeded (did not revert), then totalSupply is unchanged and the sum of the two observed balances changed by exactly zero
        //    apart from movement between them: (balFromBefore - balFromAfter) == (balToAfter - balToBefore) == amount OR transfer may have been from a different sender,
        //    so we conservatively assert that totalSupply unchanged and net sum of all observed balances (balFrom + balTo) changes by zero and equals totalSupply difference.
        // 2) If the 'to' address is the zero address, transfer must revert (this is a rule of C._transfer).

        // We express this as a single boolean formula below.
        bool toIsZero = (to == address(0));

        // change in observed pair-sum
        // using no underflow in assert: compare via additions
        uint256 sumBefore = balFromBefore + balToBefore;
        uint256 sumAfter = balFromAfter + balToAfter;

        assert(
            // transfers to zero address must revert
            (toIsZero ? reverted : true)
            &&
            // if not reverted, totalSupply unchanged and observed pair-sum unchanged
            (reverted || (totalAfter == totalBefore && sumAfter == sumBefore))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address target, bool freeze, address caller) public payable {
        // We must execute calls as this contract (msg.sender to c will be this contract).
        // The contract c was freshly deployed by the checker and its owner is the deployer (the checker deploys c),
        // so this InvMutTest is NOT the owner unless the checker passed it that way. To test both cases,
        // we will attempt freezeAccount and observe whether it reverts, then check relation between revert and frozenAccount value.

        // read before value
        bool before = c.frozenAccount(target);

        // attempt call and record revert
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after value
        bool after = c.frozenAccount(target);

        // General rule: if the call succeeded (did not revert), then the frozenAccount[target] equals freeze;
        // if it reverted, the frozenAccount[target] must remain unchanged (after == before).
        assert((!reverted && after == freeze) || (reverted && after == before));
    }

    receive() external payable {}
}

