contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: caller is this contract (owner initially), try to burn amount by calling burn via try/catch
    function run(uint256 burnAmount) public payable {
        // No precondition on burnAmount; it may be larger than balance to force revert.
        // Read before-values
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeTotal = c.totalSupply();
        // attempt burn and record whether it reverted
        bool reverted;
        try c.burn(burnAmount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Read after-values
        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterTotal = c.totalSupply();
        // General rule: if burn reverted, both balance and totalSupply unchanged; if succeeded,
        // both decreased by exactly burnAmount and caller's balance was sufficient before.
        assert(
            (reverted && afterBalance == beforeBalance && afterTotal == beforeTotal) ||
            (!reverted && beforeBalance >= burnAmount &&
             beforeBalance - afterBalance == burnAmount &&
             beforeTotal - afterTotal == burnAmount)
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try transferring from this contract (InvMutTest is msg.sender)
    function run(address to, uint256 value, address maybeFreezeTarget, bool freeze) public payable {
        // precondition: to can be any address (including zero) and value any uint256
        // set up: ensure the InvMutTest contract has some tokens by minting to it from owner
        // The deployed c has owner = deployer (which is this contract per problem statement), so calls guarded by onlyOwner succeed.
        // mint some amount to this contract so transfers can potentially succeed
        uint256 mintAmount = value;
        c.mintToken(address(this), mintAmount);

        // optionally freeze either sender or recipient to trigger revert conditions
        c.freezeAccount(maybeFreezeTarget, freeze);

        // read balances before
        uint256 beforeFrom = c.balanceOf(address(this));
        uint256 beforeTo = c.balanceOf(to);

        // attempt transfer and capture whether it reverted
        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint256 afterFrom = c.balanceOf(address(this));
        uint256 afterTo = c.balanceOf(to);

        // The general rule:
        // If the transfer reverted then balances remain unchanged; otherwise the sender's balance decreased by value and recipient's increased by value.
        assert(reverted ? (afterFrom == beforeFrom && afterTo == beforeTo) : (afterFrom + value == beforeFrom && afterTo == beforeTo + value));
    }

    receive() external payable { }
}

