contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: fromAddr will attempt to call transfer via this contract by first minting tokens to it if caller is owner
    // We need to supply a sender address that will call c.transfer. Since the checker runs run() once and msg.sender for calls
    // from this test to c is address(this), we simulate different "sender" behavior by using only address(this) as caller.
    // So the property will consider transfers initiated by address(this) (the test contract) with arbitrary to and value.
    function run(address to, uint256 value) public payable {
        require(to != address(0)); // avoid trivially always-reverting zero-address to keep reaching assert in some executions

        // Ensure this contract has enough tokens to attempt the transfer when possible.
        // If this test contract is owner of c (it is, per harness note: this contract deployed c), mint to self first.
        // Try to mint; capture whether mint reverted.
        bool mintReverted;
        try c.mintToken(address(this), value) {
            mintReverted = false;
        } catch {
            mintReverted = true;
        }

        // Read balances and totalSupply before transfer attempt
        uint256 beforeFrom = c.balanceOf(address(this));
        uint256 beforeTo = c.balanceOf(to);

        // Attempt the transfer; capture whether it reverted
        bool transferReverted;
        try c.transfer(to, value) returns (bool ok) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        uint256 afterFrom = c.balanceOf(address(this));
        uint256 afterTo = c.balanceOf(to);

        // General rule: if transfer succeeded then from decreased by value and to increased by value; if transfer reverted then both balances unchanged.
        // Must avoid underflow in expression by using comparisons.
        assert(
            transferReverted
            ? (afterFrom == beforeFrom && afterTo == beforeTo)
            : (beforeFrom >= value && afterFrom == beforeFrom - value && afterTo == beforeTo + value)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: recipient address and transfer amount
    function run(address to, uint256 value) public payable {
        // no precondition on params; but avoid zero-address for some executions to reach assert in nontrivial cases
        // We'll allow to == address(0) as it should cause revert per contract, and that's part of property.

        // Ensure this test contract has tokens to attempt a transfer when possible by minting to self if allowed.
        bool mintReverted;
        try c.mintToken(address(this), value) {
            mintReverted = false;
        } catch {
            mintReverted = true;
        }

        // Read observable pre-state
        uint256 beforeSenderBal = c.balanceOf(address(this));
        uint256 beforeToBal = c.balanceOf(to);
        bool beforeSenderFrozen = c.frozenAccount(address(this));
        bool beforeToFrozen = c.frozenAccount(to);

        // Attempt the transfer and capture whether it reverted
        bool transferReverted;
        try c.transfer(to, value) returns (bool ok) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // Read post-state balances
        uint256 afterSenderBal = c.balanceOf(address(this));
        uint256 afterToBal = c.balanceOf(to);

        // General rule:
        // - If transfer succeeded then: to != address(0), beforeSenderBal >= value, and neither account was frozen;
        //   additionally balances changed accordingly (sender decreased by value and recipient increased by value).
        // - If transfer reverted then at least one of these required preconditions did not hold: to == address(0) OR beforeSenderBal < value OR beforeSenderFrozen OR beforeToFrozen.

        assert(
            transferReverted
            ? ( (to == address(0)) || (beforeSenderBal < value) || beforeSenderFrozen || beforeToFrozen )
            : ( to != address(0)
                && beforeSenderBal >= value
                && !beforeSenderFrozen
                && !beforeToFrozen
                && afterSenderBal == beforeSenderBal - value
                && afterToBal == beforeToBal + value )
        );
    }

    receive() external payable {}
}
